import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 109 · ANGLE: humiliated grandma + powerful stranger recognizes her (friend moved out of first class; the pilot was her foster son)

sc("""Sweetheart, my best friend Agnes saved for eleven years to fly first class, just once in her life. Christmas of two thousand twenty-three, she was seventy-nine, and she finally had the ticket. Seat two A. And ten minutes before takeoff, a flight attendant told her to get her things and move to the back of the plane, so a businessman's girlfriend could have her seat. What happened next, I saw with my own eyes.""",
   "elderly woman in first class airplane seat", "SEAT 2A")
sc("""Tonight I'm going to tell you who walked out of that cockpit, what he said into the microphone that made a whole airplane go quiet, and why that businessman wouldn't look anybody in the eye for the rest of the flight. Stay with me, honey, because it goes back to a foster home in Mansfield in nineteen seventy-nine.""",
   "airplane cockpit door opening", "WHO CAME OUT")

ch("Agnes")
sc("""Agnes and I have been friends since the second grade, honey. She married a mailman named Bill, and they couldn't have children of their own. So in nineteen sixty-eight, they became foster parents. And over the next twenty-five years, they took in forty-one children. Forty-one. Some stayed a week, some stayed ten years. Agnes kept a photograph of every single one on her refrigerator, and she knew all their birthdays by heart.""",
   "refrigerator covered with children's photographs", "FORTY-ONE CHILDREN")
sc("""They never had much money, sweetheart. Bill's mailman salary and whatever the county paid, which wasn't much. Agnes made the children's clothes and cut their hair at the kitchen table. They never took a vacation in their lives. Bill passed in two thousand twelve. And Agnes had a little dream she told only me. Just once, before she died, she wanted to fly first class. With the warm nuts and the real glass.""",
   "elderly woman cutting child's hair kitchen 1970s", "THE WARM NUTS")
sc("""Her younger sister lived in Florida, and they hadn't spent Christmas together in fifteen years. So Agnes started putting twenty dollars a month into a coffee can. Eleven years. And in October of twenty twenty-three, she bought one first-class ticket from Columbus to Tampa, for the twenty-second of December. I went with her, but I sat in the back, in coach, because I wasn't going to pay that much. In a minute I'll tell you what she wore.""",
   "coffee can full of saved money", "ELEVEN YEARS")

ch("Seat two A")
sc("""She wore her best red wool suit and the gold cross Bill gave her on their wedding day. She had her hair done the day before. When they called first class to board, she squeezed my hand so hard it hurt, and she walked down that jet bridge like a queen. I watched her sit down in seat two A from the line behind her. She ran her hand over the leather like it was a fur coat.""",
   "elderly woman in red suit boarding airplane", "LIKE A QUEEN")
sc("""I was in row twenty-eight, sweetheart, by the bathroom. And about ten minutes before the doors closed, I saw a flight attendant coming down the aisle with Agnes behind her, carrying her coat and her purse and her little Christmas bag with the presents for her sister. Her face was red. The flight attendant stopped at the empty seat next to me, row twenty-eight, middle seat, and said, here you go, ma'am.""",
   "flight attendant leading elderly woman down aisle", "ROW 28, MIDDLE SEAT")
sc("""If you're enjoying Grandma's story, tap the like button for me, sweetheart. It helps more people find these stories. I said, what in the world happened? And Agnes whispered, there's a man up front who flies all the time. He wanted his lady friend to sit next to him. They said they had to reseat me. They said I'd get a voucher. And then my best friend, seventy-nine years old, in her red suit, started to cry.""",
   "elderly woman crying in cramped airplane seat", "THEY RESEATED ME")

ch("The man in two B")
sc("""I could see him from where I stood up, honey. A man about fifty, in a vest with the airline's logo on it, the kind they give to people who fly every week. A young woman with big sunglasses was settling into seat two A, into Agnes's seat, and laughing. And he said something to the flight attendant, and they both laughed. I've never wanted to march up an airplane aisle so badly in my life.""",
   "businessman laughing in first class seat", "AGNES'S SEAT")
sc("""I said, Agnes, that is not right. You paid for that seat. You saved for eleven years. I'm going up there. And Agnes grabbed my arm and said, Ruth, no. Please. Don't make a scene. I don't want to ruin anybody's Christmas. And that was Agnes, sweetheart. Forty-one children, and she didn't want to be any trouble to anybody. So I sat down. And I was boiling.""",
   "elderly woman holding friend's arm on plane", "DON'T MAKE A SCENE")

sc("""The flight attendant brought Agnes a little plastic cup of water and a voucher for fifty dollars, honey. Fifty dollars. For eleven years of coffee-can money. Agnes folded it up and put it in her purse without looking at it. And she said, it's fine, Ruth. At least I got to sit in it for ten minutes. I'll remember how it felt. I'll tell you what I wanted to do with that voucher in a minute.""",
   "small voucher envelope on tray table", "FIFTY DOLLARS")
ch("The captain")
sc("""So far, the coffee can, the red suit, the businessman, and Agnes in the middle seat by the bathroom. And just before the doors closed, the cockpit door opened, and the captain stepped out to talk to the flight attendant up front. A tall Black man, about fifty, with gray at his temples and four gold stripes on his sleeve. He glanced down the aisle. Then he looked again. Stay with me.""",
   "airline captain stepping out of cockpit", "HE LOOKED AGAIN")
sc("""He came walking down that aisle, honey, all the way back, past first class, past business, past all those rows of people with their seatbelts on, staring at him. And he stopped at row twenty-eight. And he bent down and looked at Agnes, and he said, very softly, Mama Agnes? And Agnes looked up at him, with her wet eyes, and she put her hand over her mouth. She said, Marcus?""",
   "pilot crouching beside elderly woman's seat", "MAMA AGNES?")

ch("Marcus")
sc("""Marcus came to Agnes and Bill's house in nineteen seventy-nine, when he was nine years old, sweetheart. He'd been in six homes already. He didn't talk for the first three months. Not one word. He just sat at the window and watched the airplanes from the airfield go over. And one night, Bill sat down beside him with a library book about airplanes and started reading it out loud. Marcus said his first word that night. Bill.""",
   "boy at window watching airplane 1970s", "HIS FIRST WORD")
sc("""Bill took him to the airfield every Saturday after that, to watch the small planes take off. Agnes sewed him a pilot's cap out of an old blue blazer. He stayed with them for nine years, until he graduated high school. He went into the Air Force. And they lost touch, the way you do. Agnes had his picture on her refrigerator for forty years, in that homemade blue cap. In a minute I'll tell you what he said to her.""",
   "boy in homemade blue pilot cap", "THE BLUE CAP")
sc("""He said, Mama Agnes, why are you sitting back here? And Agnes tried to say it was nothing. But I'm not Agnes, honey. I told him. All of it. The coffee can, the eleven years, seat two A, the man in the vest. And I watched that captain's face go very still. He stood up. He said, excuse me, ladies. And he walked back up the aisle to the front.""",
   "pilot walking back up airplane aisle", "EXCUSE ME, LADIES")

sc("""I found out later, honey, that Marcus had looked for Agnes for years. When he got his wings in the Air Force, he wrote to the old house on Sycamore Street, but by then Agnes had sold it and moved to a little apartment after Bill died, and the letter came back. He didn't know Bill had passed. He'd been flying over Ohio for thirty years, looking down and wondering if they were still there.""",
   "returned letter stamped return to sender", "RETURN TO SENDER")
ch("The announcement")
sc("""A minute later, the speakers crackled. And his voice came over the whole airplane. He said, ladies and gentlemen, this is your captain. Before we leave, I want to tell you about a passenger. In nineteen seventy-nine, I was a little boy nobody wanted. I'd been in six foster homes. And a mailman and his wife took me in, and they taught me to read, and they taught me to love airplanes.""",
   "airplane passengers listening to announcement", "A BOY NOBODY WANTED")
sc("""He said, that woman raised forty-one children who weren't her own. She saved for eleven years for seat two A on this flight. And a few minutes ago, she was moved to the back of my airplane. Then he said, I'm the captain of this aircraft. And Mrs. Agnes Hoyt will be sitting in seat two A. There was a silence, honey. And then somebody started clapping. And then the whole airplane was clapping.""",
   "entire airplane cabin applauding", "SEAT 2A IS HERS")

ch("The walk")
sc("""The flight attendant came back to row twenty-eight, with her face as red as Agnes's suit, and she said, Mrs. Hoyt, I am so sorry, please, come with me. And Agnes walked back up that aisle, honey, with her Christmas bag, and people were reaching out to touch her arm. A sailor in uniform stood up. An old man saluted. Agnes was crying so hard she couldn't see where she was going.""",
   "elderly woman walking up airplane aisle applause", "THE WALK UP THE AISLE")
sc("""The young woman in the sunglasses had already moved, without being asked. She went back to row twenty-eight and sat right next to me, and she said, quietly, I'm so sorry, I didn't know. And I'll give her credit. She meant it. But the man in the vest, sweetheart, didn't look up from his phone for the rest of the flight. Not once. Two hours and twenty minutes, staring at that phone.""",
   "businessman staring at phone avoiding eyes", "HE NEVER LOOKED UP")

ch("Tampa")
sc("""When we landed in Tampa, Marcus asked Agnes to stay on the plane until everyone was off. Then he took her into the cockpit and let her sit in the captain's seat. And he reached into his flight bag, honey, and pulled out a little folded square of blue cloth, faded and worn soft. It was the cap. The homemade pilot's cap Agnes sewed from Bill's old blazer. He'd carried it on every single flight for thirty years.""",
   "faded homemade blue cap in pilot's hand", "EVERY SINGLE FLIGHT")
sc("""Marcus spent Christmas Day with Agnes and her sister, sweetheart, and his wife and his two daughters drove over from Orlando. And now every Christmas, he flies Agnes to Tampa himself. First class, seat two A. She's eighty-two now. And the man in the vest? Agnes got a letter from the airline in January, with an apology and two free tickets. She gave them both to a young foster mother at her church.""",
   "elderly woman with pilot's family Christmas", "SEAT 2A EVERY CHRISTMAS")

ch("Grandma's lesson")
sc("""Here's what I want you to remember, honey. You never know who that old woman in the back of the line used to be, or who she raised. Treat her like she matters, because to somebody, she's the whole world. Tell me in the comments, sweetheart, is there someone who raised you who wasn't your family? There are more of my family's stories in the playlist right there on your screen. Good night. Merry Christmas.""",
   "airplane window at sunset over clouds", "SHE MATTERS")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma109", "Airline Moved Grandma to the BACK of the Plane. Then the Pilot Saw Her",
     ["Grandma Ruth is a fictional narrator, and this is a fictional story. All names are invented, and no real airline is depicted."],
     "humiliated grandma story", minutes=(12, 14.5), voice="en_US-lessac-high")
